-- Dry run for 20261022_pricing_cost_basis.sql (step 1) and 20261022_pricing_cost_basis_cutover.sql (step 2).
-- Generated by scripts/build-pricing-dry-run.mjs; do not edit. Runs on live inside one transaction that always
-- raises, so nothing is kept. Compares every resolved price before, after step 1, after step 2 and after both
-- rollbacks, fingerprints the objects origin/main uses, and replays origin/main's writes and calls at each stage.
begin;
select set_config('request.jwt.claim.role', 'service_role', true);
select set_config('request.jwt.claims', '{"role":"service_role"}', true);

create or replace function pg_temp.sim_main() returns jsonb language plpgsql as $sim$
declare
  r jsonb := '{}'::jsonb;
  v_pid uuid;
  v_nocost uuid;
  v_price numeric;
  v_company uuid;
  v_contact uuid;
  v_order uuid;
  v_quote uuid;
  v_claims text := current_setting('request.jwt.claims', true);
begin
  begin
    -- Order numbers come from a sequence, which a rollback does not undo. Inside this sub-transaction
    -- (always undone) use a throwaway number so the dry run leaves no gap in live order numbering.
    execute $nx$create or replace function public.next_order_number() returns text language sql as
      $q$ select 'DRYRUN-' || substr(md5(random()::text), 1, 10) $q$$nx$;
    -- CRM product create (main writes the retail price itself) and cost upsert.
    begin
      insert into public.products (name, sku, category_id, price, moq, stock_qty, status, catalogue_access, visibility)
      values ('DRYRUN main product', 'DRYRUN-MAIN-' || substr(md5(random()::text), 1, 8), (select id from public.categories limit 1),
              777, 10, 0, 'active', 'all', 'catalogue')
      returning id into v_pid;
      insert into public.product_costs (product_id, supplier_cost, updated_at) values (v_pid, 500, now())
      on conflict (product_id) do update set supplier_cost = excluded.supplier_cost, updated_at = excluded.updated_at;
      select price into v_price from public.products where id = v_pid;
      r := r || jsonb_build_object('create_ok', true, 'create_price_stored', v_price);
    exception when others then r := r || jsonb_build_object('create_error', sqlerrm);
    end;
    -- CRM product edit: retail price change.
    begin
      update public.products set price = 888 where id = v_pid;
      select price into v_price from public.products where id = v_pid;
      r := r || jsonb_build_object('edit_price_stored', v_price);
    exception when others then r := r || jsonb_build_object('edit_error', sqlerrm);
    end;
    -- What main shows (retail 888, Viral = 888 x 1.25) vs what the database charges for that product.
    begin
      r := r || jsonb_build_object(
        'new_product_corporate_db', public.listed_unit_price(null, v_pid, 888, null, null),
        'new_product_viral_db', public.listed_unit_price('8462149f-7a2a-4f6d-bd34-894604782060', v_pid, 888, 25, null),
        'new_product_tcs_db', public.listed_unit_price('607b71d6-b58a-41ed-aa44-e3672f8b7c68', v_pid, 888, 0, null),
        'new_product_store_db', public.portal_unit_price('store', v_pid, null, 888, null, null, null, null));
    exception when others then r := r || jsonb_build_object('price_error', sqlerrm);
    end;
    -- CSV import by an account without cost access: product with a price and no cost row.
    begin
      insert into public.products (name, sku, price, moq, status, catalogue_access, visibility)
      values ('DRYRUN no cost', 'DRYRUN-NOCOST-' || substr(md5(random()::text), 1, 8), 450, 1, 'active', 'all', 'catalogue')
      returning id into v_nocost;
      r := r || jsonb_build_object(
        'no_cost_corporate_db', public.listed_unit_price(null, v_nocost, 450, null, null),
        'no_cost_store_db', public.portal_unit_price('store', v_nocost, null, 450, null, null, null, null));
    exception when others then r := r || jsonb_build_object('no_cost_error', sqlerrm);
    end;
    -- Company special price upsert (special-price-actions: on conflict company_id, product_id).
    begin
      insert into public.company_product_prices (company_id, product_id, price, valid_until, updated_at)
      values ('607b71d6-b58a-41ed-aa44-e3672f8b7c68', v_pid, 600, null, now())
      on conflict (company_id, product_id) do update set price = excluded.price, valid_until = excluded.valid_until, updated_at = excluded.updated_at;
      r := r || jsonb_build_object('special_upsert_ok', true, 'special_tcs_db', public.listed_unit_price('607b71d6-b58a-41ed-aa44-e3672f8b7c68', v_pid, 888, 0, null));
    exception when others then r := r || jsonb_build_object('special_error', sqlerrm);
    end;
    -- Settings save (main's columns only).
    begin
      update public.org_settings set default_margin_percent = default_margin_percent, b2c_margin_percent = b2c_margin_percent,
        b2b_margin_percent = b2b_margin_percent, crm_use_best_cost = crm_use_best_cost, portal_use_best_cost = portal_use_best_cost,
        store_show_sell_price = store_show_sell_price, portal_show_sell_price = portal_show_sell_price;
      r := r || jsonb_build_object('settings_ok', true);
    exception when others then r := r || jsonb_build_object('settings_error', sqlerrm);
    end;
    -- Portal gift list reads (main's column list).
    begin
      perform v.id, v.name, v.sku, v.description, v.image_url, v.price, v.moq, v.category_name, v.brand_name, v.stock_qty, v.fulfillment_mode
      from public.client_products v limit 5;
      r := r || jsonb_build_object('client_products_ok', true);
    exception when others then r := r || jsonb_build_object('client_products_error', sqlerrm);
    end;
    -- Public store checkout: guest company + contact + place_direct_order (service role), as main does.
    begin
      insert into public.companies (name) values ('DRYRUN store buyer') returning id into v_company;
      insert into public.contacts (company_id, full_name, email) values (v_company, 'Dry Run', 'dryrun@example.invalid') returning id into v_contact;
      v_order := public.place_direct_order(v_company, v_contact, null, 'store', null,
        jsonb_build_array(jsonb_build_object('product_id', '096918f4-d95e-4688-92ab-9c337978501c', 'quantity', 1)), 'store');
      r := r || jsonb_build_object('store_order', (select jsonb_agg(jsonb_build_object('unit_price', oi.unit_price, 'line_total', oi.line_total))
        from public.order_items oi where oi.order_id = v_order),
        'store_order_cost', (select jsonb_object_agg(e.key, e.value) from public.orders o, jsonb_each(to_jsonb(o)) e
          where o.id = v_order and e.key ilike '%cost%'));
    exception when others then r := r || jsonb_build_object('store_order_error', sqlerrm);
    end;
    -- Corporate portal order for Viral Inbound (service role). place_direct_order builds an
    -- on-commit-drop temp table; in production each call is its own transaction, so drop it here.
    drop table if exists pg_temp._direct_lines;
    begin
      v_order := public.place_direct_order('8462149f-7a2a-4f6d-bd34-894604782060', null, null, 'portal', null,
        jsonb_build_array(jsonb_build_object('product_id', '096918f4-d95e-4688-92ab-9c337978501c', 'quantity', 1)), 'portal');
      r := r || jsonb_build_object('viral_order', (select jsonb_agg(jsonb_build_object('unit_price', oi.unit_price, 'line_total', oi.line_total))
        from public.order_items oi where oi.order_id = v_order),
        'viral_order_cost', (select jsonb_object_agg(e.key, e.value) from public.orders o, jsonb_each(to_jsonb(o)) e
          where o.id = v_order and e.key ilike '%cost%'));
    exception when others then r := r || jsonb_build_object('viral_order_error', sqlerrm);
    end;
    -- Staff converts an accepted quotation (CRM): exercises the order-cost statement.
    begin
      select q.id into v_quote from public.quotations q
      where exists (select 1 from public.quotation_items qi where qi.quotation_id = q.id and qi.product_id is not null)
        and not exists (select 1 from public.orders o where o.quotation_id = q.id)
      order by q.created_at desc limit 1;
      update public.quotations set status = 'accepted' where id = v_quote;
      perform set_config('request.jwt.claims', json_build_object('role', 'service_role', 'sub', 'bc6940e8-1d60-4519-b9ec-73eac5226ad7')::text, true);
      perform set_config('request.jwt.claim.sub', 'bc6940e8-1d60-4519-b9ec-73eac5226ad7', true);
      v_order := public.convert_quotation_to_order(v_quote);
      r := r || jsonb_build_object('convert_ok', v_order is not null, 'convert_order_cost',
        (select to_jsonb(o) -> 'total_cost' from public.orders o where o.id = v_order));
    exception when others then r := r || jsonb_build_object('convert_error', sqlerrm);
    end;
    raise exception 'SIM_UNDO';
  exception when others then
    if sqlerrm <> 'SIM_UNDO' then r := r || jsonb_build_object('sim_error', sqlerrm); end if;
  end;
  perform set_config('request.jwt.claims', coalesce(v_claims, '{"role":"service_role"}'), true);
  perform set_config('request.jwt.claim.sub', '', true);
  return r;
end
$sim$;


create temporary table _fp_before on commit drop as
select 'fn:' || p.oid::regprocedure::text as k, md5(pg_get_functiondef(p.oid)) as v
from pg_proc p join pg_namespace n on n.oid = p.pronamespace
where n.nspname = 'public' and p.proname in ('portal_unit_price', 'listed_unit_price', 'place_direct_order',
  'client_respond_quotation', 'convert_quotation_to_order', 'place_quote_order', 'best_supplier_cost', 'resolved_sell_price')
union all
select 'view:' || c.relname, md5(pg_get_viewdef(c.oid)) from pg_class c join pg_namespace n on n.oid = c.relnamespace
where n.nspname = 'public' and c.relname in ('client_products', 'portal_catalogue')
union all
select 'triggers:products', md5(coalesce(string_agg(t.tgname || pg_get_triggerdef(t.oid), ',' order by t.tgname), ''))
from pg_trigger t where t.tgrelid = 'public.products'::regclass and not t.tgisinternal
union all
select 'col:products.price', md5(coalesce(a.attnotnull::text, '') || coalesce(pg_get_expr(d.adbin, d.adrelid), ''))
from pg_attribute a left join pg_attrdef d on d.adrelid = a.attrelid and d.adnum = a.attnum
where a.attrelid = 'public.products'::regclass and a.attname = 'price'
union all
select 'data:products', md5(coalesce(string_agg(id::text || ':' || price::text || ':' || status::text, ',' order by id), '')) from public.products
union all
select 'data:product_costs', md5(coalesce(string_agg(product_id::text || ':' || coalesce(supplier_cost::text, '-'), ',' order by product_id), '')) from public.product_costs
union all
select 'data:company_product_prices', md5(coalesce(string_agg(company_id::text || product_id::text || price::text || coalesce(valid_until::text, '-'), ',' order by company_id, product_id), '')) from public.company_product_prices
union all
select 'data:portal_product_prices', md5(coalesce(string_agg(product_id::text || portal || price::text, ',' order by product_id, portal), '')) from public.portal_product_prices
union all
select 'data:org_settings', md5(coalesce(string_agg(
  concat_ws('|', s.store_price_base, s.business_price_base, s.corporate_price_base, s.store_margin_percent, s.business_margin_percent,
    s.corporate_margin_percent, s.store_no_cost_fallback, s.business_no_cost_fallback, s.corporate_no_cost_fallback,
    s.default_margin_percent, s.b2c_margin_percent, s.b2b_margin_percent, s.corporate_rounding), ','), '')) from public.org_settings s
union all
select 'data:price_change_log', count(*)::text from public.price_change_log
;


create temporary table _snap_before on commit drop as
with comp as (select id, margin_percent from public.companies),
cat_co as (
  select cp.id as cp_id, x.company_id
  from public.campaign_products cp
  join lateral (
    select c.company_id from public.campaigns c where c.id = cp.campaign_id and c.company_id is not null
    union select a.company_id from public.catalog_assignments a where a.campaign_id = cp.campaign_id
    union select cp.priced_company_id where cp.priced_company_id is not null
  ) x on true
)
select 'store'::text as kind, p.id as product_id, p.status::text as status, null::uuid as company_id, null::uuid as line_id,
       public.portal_unit_price('store', p.id, null, p.price, null, null, null, null) as price
from public.products p
union all
select 'business', p.id, p.status::text, null, null,
       public.portal_unit_price('business', p.id, null, p.price, null, null, null, null)
from public.products p
union all
select 'business_company', p.id, p.status::text, c.id, null,
       public.portal_unit_price('business', p.id, c.id, p.price, null, c.margin_percent, null, null)
from public.products p cross join comp c
union all
select 'corporate', p.id, p.status::text, null, null,
       public.portal_unit_price('corporate', p.id, null, p.price, null, null, null, null)
from public.products p
union all
select 'corporate_company', p.id, p.status::text, c.id, null,
       public.listed_unit_price(c.id, p.id, p.price, c.margin_percent, null)
from public.products p cross join comp c
union all
select 'catalog_line', p.id, p.status::text, cc.company_id, cp.id,
       case when cp.pack_option is not null then cp.selling_price
            else public.listed_unit_price(cc.company_id, p.id, p.price, c.margin_percent, cp.manual_price) end
from public.campaign_products cp
join public.products p on p.id = cp.product_id
join cat_co cc on cc.cp_id = cp.id
join comp c on c.id = cc.company_id
union all
select 'client_products_view', v.id, 'active', null, null, v.price from public.client_products v
;

create temporary table _sim on commit drop as select 'before'::text as stage, pg_temp.sim_main() as result;

-- Step 1: schema only.
-- Pricing phase 1, step 1 of 2: cost-basis SCHEMA ONLY (additive, backward compatible).
--
-- Safe to apply while production still runs origin/main: it adds columns with defaults, one new table
-- and one new function, and changes no existing function, view, trigger, setting or price.
--   * org_settings.{store,business,corporate}_default_cost_source (manual | preferred | lowest, default manual)
--   * product_costs.cost_source (portal_default | manual | preferred | lowest, default portal_default)
--   * public.company_pricing_portal(company) (business or corporate; nothing calls it yet)
--   * public.effective_product_cost(product, quantity, portal) (service_role only; nothing calls it yet)
--   * public.portal_product_margins (per-product margin per portal; empty)
--   * portal_product_prices.source, company_product_prices.source (default manual),
--     company_product_prices.portal (null = business and corporate, exactly as today)
-- origin/main keeps working unchanged: it never names these columns, product_costs upserts and
-- company_product_prices upserts (on company_id, product_id) still succeed, and every price is the same.
--
-- Step 2, 20261022_pricing_cost_basis_cutover.sql, switches pricing to cost. Apply it only together with
-- the deploy of the matching app code (it is NOT compatible with origin/main; see that file).
--
-- Cost source rules (portal_default first resolves to that portal's default_cost_source):
--     manual    product_costs.supplier_cost (default, every product on day one)
--     preferred the pinned preferred supplier offer when it is eligible, else the manual cost
--     lowest    the best eligible offer (a pinned preferred offer wins), else the manual cost
--   Eligible: active, in stock when org_settings.best_cost_require_in_stock, and moq <= quantity
--   (quantity defaults to the product MOQ for listed prices).
--   src/lib/pricing/cost-basis.ts mirrors effective_product_cost.
--
-- Phase 2 TODO: quantity tiers (offer and sell), per-portal company margins, supplier currency and FX,
-- GST-inclusive supplier costs (phase 1 treats every cost as INR excluding GST), stale-offer expiry.
--
-- Do not apply from the agent. Rollback: supabase/rollbacks/20261022_pricing_cost_basis_rollback.sql
-- Dry run: supabase/tests/pricing_cost_basis_check.sql (built by scripts/build-pricing-dry-run.mjs).

-- 1. Cost basis: a default per portal, an override per product ---------------------------------
-- Each portal rule has a default cost source (manual on day one). A product follows the portal default
-- unless it picks manual, preferred or lowest, which then applies on every portal.
alter table public.org_settings
  add column if not exists store_default_cost_source text not null default 'manual',
  add column if not exists business_default_cost_source text not null default 'manual',
  add column if not exists corporate_default_cost_source text not null default 'manual';

-- Every existing product gets portal_default (the column default). Portal defaults are manual, so the
-- effective cost is the stored supplier_cost for every product, as today.
alter table public.product_costs
  add column if not exists cost_source text not null default 'portal_default';

do $$
begin
  if not exists (select 1 from pg_constraint where conname = 'product_costs_cost_source_check') then
    alter table public.product_costs
      add constraint product_costs_cost_source_check check (cost_source in ('portal_default', 'manual', 'preferred', 'lowest'));
  end if;
  if not exists (select 1 from pg_constraint where conname = 'org_settings_default_cost_source_check') then
    alter table public.org_settings
      add constraint org_settings_default_cost_source_check check (
        store_default_cost_source in ('manual', 'preferred', 'lowest')
        and business_default_cost_source in ('manual', 'preferred', 'lowest')
        and corporate_default_cost_source in ('manual', 'preferred', 'lowest'));
  end if;
end $$;

comment on column public.product_costs.cost_source is
  'portal_default = the portal rule''s default_cost_source. manual = supplier_cost. preferred = pinned preferred offer when eligible, else supplier_cost. lowest = best eligible offer (pinned preferred wins), else supplier_cost. A product value other than portal_default applies on every portal.';
comment on column public.org_settings.store_default_cost_source is 'Cost source for Retail (store) prices of products set to portal_default: manual | preferred | lowest.';
comment on column public.org_settings.business_default_cost_source is 'Cost source for business prices of products set to portal_default: manual | preferred | lowest.';
comment on column public.org_settings.corporate_default_cost_source is 'Cost source for corporate prices of products set to portal_default: manual | preferred | lowest.';

-- Which portal a company's quotes and orders price on.
create or replace function public.company_pricing_portal(p_company_id uuid)
returns text
language sql
stable
security definer
set search_path = public
as $$
  select case when (select c.account_type from public.companies c where c.id = p_company_id) = 'business'
              then 'business' else 'corporate' end;
$$;
revoke all on function public.company_pricing_portal(uuid) from public, anon, authenticated;
grant execute on function public.company_pricing_portal(uuid) to service_role;

create or replace function public.effective_product_cost(p_product_id uuid, p_quantity integer default null, p_portal text default null)
returns numeric
language plpgsql
stable
security definer
set search_path = public
as $$
declare
  v_source text;
  v_manual numeric;
  v_qty integer;
  v_require_stock boolean;
  v_offer numeric;
begin
  if p_product_id is null then
    return null;
  end if;

  select pc.cost_source, pc.supplier_cost
    into v_source, v_manual
  from public.product_costs pc
  where pc.product_id = p_product_id;

  -- No portal (or an unknown one) means the manual cost for portal_default products.
  v_source := coalesce(v_source, 'portal_default');
  if v_source = 'portal_default' then
    select case p_portal
             when 'store' then s.store_default_cost_source
             when 'business' then s.business_default_cost_source
             when 'corporate' then s.corporate_default_cost_source
           end
      into v_source
    from public.org_settings s
    limit 1;
    v_source := coalesce(v_source, 'manual');
  end if;
  if v_source not in ('preferred', 'lowest') then
    return v_manual;
  end if;

  -- Listed prices use the product MOQ, so an offer that needs more than the MOQ is not used for them.
  v_qty := coalesce(
    p_quantity,
    (select greatest(coalesce(p.moq, 1), 1) from public.products p where p.id = p_product_id),
    1
  );

  if v_source = 'preferred' then
    select coalesce(s.best_cost_require_in_stock, true) into v_require_stock from public.org_settings s limit 1;
    v_require_stock := coalesce(v_require_stock, true);
    select o.cost into v_offer
    from public.product_supplier_offers o
    where o.product_id = p_product_id
      and o.is_preferred
      and o.is_active
      and (not v_require_stock or o.in_stock)
      and o.moq <= v_qty
    limit 1;
  else
    v_offer := public.best_supplier_cost(p_product_id, v_qty);
  end if;

  -- TODO phase 2: quantity tiers, supplier currency/FX, GST-inclusive costs, stale offers.
  return coalesce(v_offer, v_manual);
end;
$$;

comment on function public.effective_product_cost(uuid, integer, text) is
  'The one cost every sell price and order cost is built from. Mirrored by src/lib/pricing/cost-basis.ts.';

revoke all on function public.effective_product_cost(uuid, integer, text) from public, anon, authenticated;
grant execute on function public.effective_product_cost(uuid, integer, text) to service_role;

-- 2. Per-product portal margin ---------------------------------------------------------------
create table if not exists public.portal_product_margins (
  product_id uuid not null references public.products (id) on delete cascade,
  portal text not null check (portal in ('store', 'business', 'corporate')),
  margin_percent numeric not null check (margin_percent >= 0),
  updated_by uuid references public.profiles (id),
  created_at timestamptz not null default now(),
  updated_at timestamptz not null default now(),
  primary key (product_id, portal)
);

comment on table public.portal_product_margins is
  'Margin over cost for one product on one portal. Below fixed prices and the company margin, above the portal default margin.';

alter table public.portal_product_margins enable row level security;
revoke all on table public.portal_product_margins from public, anon;
grant select, insert, update, delete on table public.portal_product_margins to authenticated;
grant all on table public.portal_product_margins to service_role;

drop policy if exists portal_product_margins_read on public.portal_product_margins;
create policy portal_product_margins_read
  on public.portal_product_margins
  for select
  using (public.is_pricing_viewer());

drop policy if exists portal_product_margins_write on public.portal_product_margins;
create policy portal_product_margins_write
  on public.portal_product_margins
  for all
  using (public.is_pricing_editor())
  with check (public.is_pricing_editor());

-- 3. Where a fixed price came from; company prices for one portal ------------------------------
alter table public.portal_product_prices
  add column if not exists source text not null default 'manual';
alter table public.company_product_prices
  add column if not exists source text not null default 'manual';
alter table public.company_product_prices
  add column if not exists portal text;

do $$
begin
  if not exists (select 1 from pg_constraint where conname = 'portal_product_prices_source_check') then
    alter table public.portal_product_prices
      add constraint portal_product_prices_source_check check (source in ('manual', 'migrated_from_retail'));
  end if;
  if not exists (select 1 from pg_constraint where conname = 'company_product_prices_source_check') then
    alter table public.company_product_prices
      add constraint company_product_prices_source_check check (source in ('manual', 'migrated_from_retail'));
  end if;
  if not exists (select 1 from pg_constraint where conname = 'company_product_prices_portal_check') then
    alter table public.company_product_prices
      add constraint company_product_prices_portal_check check (portal is null or portal in ('business', 'corporate'));
  end if;
end $$;

comment on column public.company_product_prices.portal is
  'Null = business and corporate (as before). business or corporate = that portal only.';

select set_config('request.jwt.claim.role', 'service_role', true);

create temporary table _fp_schema on commit drop as
select 'fn:' || p.oid::regprocedure::text as k, md5(pg_get_functiondef(p.oid)) as v
from pg_proc p join pg_namespace n on n.oid = p.pronamespace
where n.nspname = 'public' and p.proname in ('portal_unit_price', 'listed_unit_price', 'place_direct_order',
  'client_respond_quotation', 'convert_quotation_to_order', 'place_quote_order', 'best_supplier_cost', 'resolved_sell_price')
union all
select 'view:' || c.relname, md5(pg_get_viewdef(c.oid)) from pg_class c join pg_namespace n on n.oid = c.relnamespace
where n.nspname = 'public' and c.relname in ('client_products', 'portal_catalogue')
union all
select 'triggers:products', md5(coalesce(string_agg(t.tgname || pg_get_triggerdef(t.oid), ',' order by t.tgname), ''))
from pg_trigger t where t.tgrelid = 'public.products'::regclass and not t.tgisinternal
union all
select 'col:products.price', md5(coalesce(a.attnotnull::text, '') || coalesce(pg_get_expr(d.adbin, d.adrelid), ''))
from pg_attribute a left join pg_attrdef d on d.adrelid = a.attrelid and d.adnum = a.attnum
where a.attrelid = 'public.products'::regclass and a.attname = 'price'
union all
select 'data:products', md5(coalesce(string_agg(id::text || ':' || price::text || ':' || status::text, ',' order by id), '')) from public.products
union all
select 'data:product_costs', md5(coalesce(string_agg(product_id::text || ':' || coalesce(supplier_cost::text, '-'), ',' order by product_id), '')) from public.product_costs
union all
select 'data:company_product_prices', md5(coalesce(string_agg(company_id::text || product_id::text || price::text || coalesce(valid_until::text, '-'), ',' order by company_id, product_id), '')) from public.company_product_prices
union all
select 'data:portal_product_prices', md5(coalesce(string_agg(product_id::text || portal || price::text, ',' order by product_id, portal), '')) from public.portal_product_prices
union all
select 'data:org_settings', md5(coalesce(string_agg(
  concat_ws('|', s.store_price_base, s.business_price_base, s.corporate_price_base, s.store_margin_percent, s.business_margin_percent,
    s.corporate_margin_percent, s.store_no_cost_fallback, s.business_no_cost_fallback, s.corporate_no_cost_fallback,
    s.default_margin_percent, s.b2c_margin_percent, s.b2b_margin_percent, s.corporate_rounding), ','), '')) from public.org_settings s
union all
select 'data:price_change_log', count(*)::text from public.price_change_log
;


create temporary table _snap_schema on commit drop as
with comp as (select id, margin_percent from public.companies),
cat_co as (
  select cp.id as cp_id, x.company_id
  from public.campaign_products cp
  join lateral (
    select c.company_id from public.campaigns c where c.id = cp.campaign_id and c.company_id is not null
    union select a.company_id from public.catalog_assignments a where a.campaign_id = cp.campaign_id
    union select cp.priced_company_id where cp.priced_company_id is not null
  ) x on true
)
select 'store'::text as kind, p.id as product_id, p.status::text as status, null::uuid as company_id, null::uuid as line_id,
       public.portal_unit_price('store', p.id, null, p.price, null, null, null, null) as price
from public.products p
union all
select 'business', p.id, p.status::text, null, null,
       public.portal_unit_price('business', p.id, null, p.price, null, null, null, null)
from public.products p
union all
select 'business_company', p.id, p.status::text, c.id, null,
       public.portal_unit_price('business', p.id, c.id, p.price, null, c.margin_percent, null, null)
from public.products p cross join comp c
union all
select 'corporate', p.id, p.status::text, null, null,
       public.portal_unit_price('corporate', p.id, null, p.price, null, null, null, null)
from public.products p
union all
select 'corporate_company', p.id, p.status::text, c.id, null,
       public.listed_unit_price(c.id, p.id, p.price, c.margin_percent, null)
from public.products p cross join comp c
union all
select 'catalog_line', p.id, p.status::text, cc.company_id, cp.id,
       case when cp.pack_option is not null then cp.selling_price
            else public.listed_unit_price(cc.company_id, p.id, p.price, c.margin_percent, cp.manual_price) end
from public.campaign_products cp
join public.products p on p.id = cp.product_id
join cat_co cc on cc.cp_id = cp.id
