delete from public.price_change_log l
where l.actor_id is null and l.product_id is null and l.company_id is null
  and l.field in ('price_base', 'margin_percent', 'no_cost_fallback')
  and l.created_at in (select m.created_at from public.price_change_log m where m.field = 'migrated_from_retail');
delete from public.price_change_log where field = 'migrated_from_retail';

update public.org_settings
set corporate_price_base = 'retail',
    corporate_margin_percent = null,
    store_no_cost_fallback = 'retail_margin',
    business_no_cost_fallback = 'retail_margin',
    corporate_no_cost_fallback = 'retail_margin';

